/**
 * Signal Outcome Logger v1.0
 *
 * Tracks every signal generated by the 5-Stage AI Trading Machine
 * Logs: WIN, LOSS, SKIP outcomes + actual R:R achieved
 *
 * Purpose: Measure accuracy over time, identify best-performing archetypes,
 * retrain ML models on real outcomes
 */

import { writeFileSync, readFileSync, existsSync, appendFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

// ============================================================================
// [1] SIGNAL LOGGER
// ============================================================================

export class SignalOutcomeLogger {
  constructor(logDir = "./data/signals") {
    this.logDir = logDir;
    this.logFilePath = join(logDir, "signal_outcomes.jsonl");
    this.statsFilePath = join(logDir, "signal_stats.json");

    this.ensureLogDirectory();
    this.loadStats();
  }

  ensureLogDirectory() {
    if (!existsSync(this.logDir)) {
      mkdirSync(this.logDir, { recursive: true });
    }
  }

  loadStats() {
    if (existsSync(this.statsFilePath)) {
      try {
        this.stats = JSON.parse(readFileSync(this.statsFilePath, "utf8"));
      } catch (e) {
        this.stats = this.createEmptyStats();
      }
    } else {
      this.stats = this.createEmptyStats();
    }
  }

  createEmptyStats() {
    return {
      totalSignals: 0,
      totalDecisions: 0,
      outcomes: {
        WIN: 0,
        LOSS: 0,
        SKIP: 0,
        PENDING: 0
      },
      archetypes: {
        BREAKOUT: { total: 0, wins: 0, losses: 0, skips: 0, winRate: 0 },
        PULLBACK: { total: 0, wins: 0, losses: 0, skips: 0, winRate: 0 },
        MOMENTUM: { total: 0, wins: 0, losses: 0, skips: 0, winRate: 0 },
        TREND_CONTINUATION: { total: 0, wins: 0, losses: 0, skips: 0, winRate: 0 },
        REVERSAL: { total: 0, wins: 0, losses: 0, skips: 0, winRate: 0 }
      },
      totalPnL: 0,
      avgRMultiple: 0,
      avgConfidenceScore: 0,
      confidenceAccuracy: {}, // { "70-75": { correct: 10, total: 20 }, ... }
      lastUpdated: null
    };
  }

  /**
   * Log a new signal when generated (Stage 2)
   */
  logSignalGenerated(signal) {
    const entry = {
      id: `SIGNAL_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      timestamp: new Date().toISOString(),
      eventType: "SIGNAL_GENERATED",
      symbol: signal.symbol,
      archetype: signal.archetype,
      confidenceScore: signal.confidenceScore,
      direction: signal.direction,
      currentPrice: signal.currentPrice,
      isValidSetup: signal.isValidSetup,
      status: "PENDING"
    };

    this.appendToLog(entry);
    this.stats.totalSignals++;
    this.saveStats();

    return entry.id;
  }

  /**
   * Log human decision (Stage 5)
   */
  logHumanDecision(signalId, decision, tradePlan) {
    const entry = {
      signalId,
      timestamp: new Date().toISOString(),
      eventType: "HUMAN_DECISION",
      decision, // APPROVE, WATCHLIST, REJECT
      tradePlan: {
        entryPrice: tradePlan.entryZone?.idealTrigger || tradePlan.currentPrice,
        stopLoss: tradePlan.stopLoss?.price,
        target: tradePlan.profitTargets?.target2,
        riskRewardRatio: tradePlan.riskRewardRatio,
        quantity: tradePlan.quantity
      }
    };

    this.appendToLog(entry);
    this.stats.totalDecisions++;

    if (decision === "REJECT") {
      this.stats.outcomes.SKIP++;
    }

    this.saveStats();

    return entry;
  }

  /**
   * Log trade outcome after execution
   */
  logTradeOutcome(signalId, outcome) {
    const entry = {
      signalId,
      timestamp: new Date().toISOString(),
      eventType: "TRADE_OUTCOME",
      outcome: outcome.result, // WIN or LOSS
      entryPrice: outcome.entryPrice,
      exitPrice: outcome.exitPrice,
      pnl: outcome.pnl,
      pnlPercent: outcome.pnlPercent,
      rMultiple: outcome.rMultiple,
      barsHeld: outcome.barsHeld,
      exitReason: outcome.exitReason // HIT_TARGET, HIT_STOP, TIME_EXIT, MANUAL
    };

    this.appendToLog(entry);

    // Update stats
    if (outcome.result === "WIN") {
      this.stats.outcomes.WIN++;
    } else if (outcome.result === "LOSS") {
      this.stats.outcomes.LOSS++;
    }

    this.stats.totalPnL += outcome.pnl || 0;

    // Update archetype stats (lookup from signal history)
    const signalEntry = this.findSignalById(signalId);
    if (signalEntry && signalEntry.archetype) {
      const arch = signalEntry.archetype;
      if (this.stats.archetypes[arch]) {
        this.stats.archetypes[arch].total++;
        if (outcome.result === "WIN") this.stats.archetypes[arch].wins++;
        if (outcome.result === "LOSS") this.stats.archetypes[arch].losses++;

        const total = this.stats.archetypes[arch].wins + this.stats.archetypes[arch].losses;
        if (total > 0) {
          this.stats.archetypes[arch].winRate = (this.stats.archetypes[arch].wins / total) * 100;
        }
      }

      // Update confidence accuracy tracking
      const confidenceBucket = this.getConfidenceBucket(signalEntry.confidenceScore);
      if (!this.stats.confidenceAccuracy[confidenceBucket]) {
        this.stats.confidenceAccuracy[confidenceBucket] = { correct: 0, total: 0, accuracy: 0 };
      }
      this.stats.confidenceAccuracy[confidenceBucket].total++;
      if (outcome.result === "WIN") {
        this.stats.confidenceAccuracy[confidenceBucket].correct++;
      }
      this.stats.confidenceAccuracy[confidenceBucket].accuracy =
        (this.stats.confidenceAccuracy[confidenceBucket].correct / this.stats.confidenceAccuracy[confidenceBucket].total) * 100;
    }

    this.saveStats();

    return entry;
  }

  /**
   * Append entry to JSONL log file
   */
  appendToLog(entry) {
    try {
      appendFileSync(this.logFilePath, JSON.stringify(entry) + "\n", "utf8");
    } catch (e) {
      console.error(`[SIGNAL_LOGGER] Failed to write log: ${e.message}`);
    }
  }

  /**
   * Save aggregated stats to JSON
   */
  saveStats() {
    this.stats.lastUpdated = new Date().toISOString();

    // Calculate aggregate metrics
    const totalOutcomes = this.stats.outcomes.WIN + this.stats.outcomes.LOSS;
    if (totalOutcomes > 0) {
      this.stats.overallWinRate = (this.stats.outcomes.WIN / totalOutcomes) * 100;
    }

    try {
      writeFileSync(this.statsFilePath, JSON.stringify(this.stats, null, 2), "utf8");
    } catch (e) {
      console.error(`[SIGNAL_LOGGER] Failed to save stats: ${e.message}`);
    }
  }

  /**
   * Find signal entry by ID from log file
   */
  findSignalById(signalId) {
    if (!existsSync(this.logFilePath)) return null;

    try {
      const lines = readFileSync(this.logFilePath, "utf8").split("\n").filter(l => l.trim());
      for (const line of lines) {
        const entry = JSON.parse(line);
        if (entry.id === signalId && entry.eventType === "SIGNAL_GENERATED") {
          return entry;
        }
      }
    } catch (e) {
      console.error(`[SIGNAL_LOGGER] Error reading log: ${e.message}`);
    }

    return null;
  }

  /**
   * Get confidence score bucket (70-75, 75-80, 80-85, 85-90, 90-95, 95-100)
   */
  getConfidenceBucket(score) {
    if (score < 70) return "below_70";
    if (score < 75) return "70-75";
    if (score < 80) return "75-80";
    if (score < 85) return "80-85";
    if (score < 90) return "85-90";
    if (score < 95) return "90-95";
    return "95-100";
  }

  /**
   * Get current statistics
   */
  getStats() {
    return this.stats;
  }

  /**
   * Get recent signals (last N)
   */
  getRecentSignals(limit = 50) {
    if (!existsSync(this.logFilePath)) return [];

    try {
      const lines = readFileSync(this.logFilePath, "utf8").split("\n").filter(l => l.trim());
      const signals = lines
        .map(line => {
          try {
            return JSON.parse(line);
          } catch {
            return null;
          }
        })
        .filter(e => e && e.eventType === "SIGNAL_GENERATED")
        .slice(-limit);

      return signals;
    } catch (e) {
      console.error(`[SIGNAL_LOGGER] Error reading signals: ${e.message}`);
      return [];
    }
  }

  /**
   * Generate performance report
   */
  generateReport() {
    const stats = this.stats;

    const totalTrades = stats.outcomes.WIN + stats.outcomes.LOSS;
    const winRate = totalTrades > 0 ? (stats.outcomes.WIN / totalTrades) * 100 : 0;

    const report = {
      summary: {
        totalSignals: stats.totalSignals,
        totalDecisions: stats.totalDecisions,
        totalTrades,
        wins: stats.outcomes.WIN,
        losses: stats.outcomes.LOSS,
        skipped: stats.outcomes.SKIP,
        winRate: Math.round(winRate * 10) / 10,
        totalPnL: Math.round(stats.totalPnL * 100) / 100
      },
      archetypePerformance: Object.keys(stats.archetypes).map(arch => {
        const data = stats.archetypes[arch];
        return {
          archetype: arch,
          total: data.total,
          wins: data.wins,
          losses: data.losses,
          winRate: Math.round(data.winRate * 10) / 10
        };
      }).sort((a, b) => b.winRate - a.winRate),
      confidenceAccuracy: Object.keys(stats.confidenceAccuracy).map(bucket => {
        const data = stats.confidenceAccuracy[bucket];
        return {
          confidenceBucket: bucket,
          total: data.total,
          correct: data.correct,
          accuracy: Math.round(data.accuracy * 10) / 10
        };
      }).sort((a, b) => a.confidenceBucket.localeCompare(b.confidenceBucket)),
      insights: this.generateInsights(stats)
    };

    return report;
  }

  /**
   * Generate actionable insights from data
   */
  generateInsights(stats) {
    const insights = [];

    // Identify best/worst archetypes
    const archetypes = Object.keys(stats.archetypes).map(arch => ({
      name: arch,
      ...stats.archetypes[arch]
    })).filter(a => a.total >= 5); // Minimum 5 trades for statistical relevance

    if (archetypes.length > 0) {
      const best = archetypes.reduce((a, b) => (a.winRate > b.winRate ? a : b));
      const worst = archetypes.reduce((a, b) => (a.winRate < b.winRate ? a : b));

      if (best.winRate > 60) {
        insights.push({
          type: "STRENGTH",
          message: `${best.name} archetype is performing exceptionally well (${best.winRate.toFixed(1)}% win rate). Consider increasing allocation.`
        });
      }

      if (worst.winRate < 40 && worst.total >= 10) {
        insights.push({
          type: "WARNING",
          message: `${worst.name} archetype is underperforming (${worst.winRate.toFixed(1)}% win rate). Review signal logic or reduce allocation.`
        });
      }
    }

    // Confidence score calibration
    const confBuckets = Object.keys(stats.confidenceAccuracy);
    for (const bucket of confBuckets) {
      const data = stats.confidenceAccuracy[bucket];
      if (data.total >= 10) {
        const expectedAccuracy = parseInt(bucket.split("-")[0]) || 70;
        const actualAccuracy = data.accuracy;

        if (actualAccuracy < expectedAccuracy - 15) {
          insights.push({
            type: "CALIBRATION_ISSUE",
            message: `Confidence bucket ${bucket} is overconfident. Expected ~${expectedAccuracy}% accuracy, actual: ${actualAccuracy.toFixed(1)}%. Recalibrate model.`
          });
        }
      }
    }

    // Sample size warning
    const totalTrades = stats.outcomes.WIN + stats.outcomes.LOSS;
    if (totalTrades < 30) {
      insights.push({
        type: "INFO",
        message: `Only ${totalTrades} trades logged. Need 50+ trades for statistical significance. Keep collecting data.`
      });
    }

    return insights;
  }

  /**
   * Export all data for ML training
   */
  exportForMLTraining() {
    if (!existsSync(this.logFilePath)) return { signals: [], outcomes: [] };

    try {
      const lines = readFileSync(this.logFilePath, "utf8").split("\n").filter(l => l.trim());
      const entries = lines.map(line => {
        try {
          return JSON.parse(line);
        } catch {
          return null;
        }
      }).filter(e => e);

      const signals = entries.filter(e => e.eventType === "SIGNAL_GENERATED");
      const outcomes = entries.filter(e => e.eventType === "TRADE_OUTCOME");

      // Join signals with outcomes
      const trainingData = [];
      for (const signal of signals) {
        const outcome = outcomes.find(o => o.signalId === signal.id);
        if (outcome) {
          trainingData.push({
            // Features
            symbol: signal.symbol,
            archetype: signal.archetype,
            confidenceScore: signal.confidenceScore,
            direction: signal.direction,
            currentPrice: signal.currentPrice,
            // Label
            label: outcome.outcome, // WIN or LOSS
            rMultiple: outcome.rMultiple
          });
        }
      }

      return {
        signals,
        outcomes,
        trainingData,
        totalSamples: trainingData.length
      };
    } catch (e) {
      console.error(`[SIGNAL_LOGGER] Export failed: ${e.message}`);
      return { signals: [], outcomes: [], trainingData: [] };
    }
  }
}

// ============================================================================
// [2] SINGLETON INSTANCE
// ============================================================================

export const signalLogger = new SignalOutcomeLogger();

// ============================================================================
// [3] CONVENIENCE FUNCTIONS
// ============================================================================

export function logSignal(signal) {
  return signalLogger.logSignalGenerated(signal);
}

export function logDecision(signalId, decision, tradePlan) {
  return signalLogger.logHumanDecision(signalId, decision, tradePlan);
}

export function logOutcome(signalId, outcome) {
  return signalLogger.logTradeOutcome(signalId, outcome);
}

export function getSignalStats() {
  return signalLogger.getStats();
}

export function getPerformanceReport() {
  return signalLogger.generateReport();
}

export default signalLogger;
